// Assuming Tree is an alias or typedef for AABBTree3 or similar CGAL-based tree structure
// and that it has methods to cast rays and count intersections.

// Generate random directions for ray casting
std::random_device rd;
std::mt19937 gen(rd());
std::uniform_real_distribution<double> dis(0.0, 1.0);

int insideCount = 0;

// Cast numberOfChecks rays in random directions
for (int i = 0; i < numberOfChecks; ++i) {
    // Generate a random direction on the unit sphere
    double theta = 2 * M_PI * dis(gen);
    double phi = std::acos(1 - 2 * dis(gen));
    double x = std::sin(phi) * std::cos(theta);
    double y = std::sin(phi) * std::sin(theta);
    double z = std::cos(phi);

    // Create a ray from point p in the random direction
    // We assume Tree has a method numberIntersectedPrimitives(Point3d, Point3d)
    // that counts intersections between a point and a direction point (ray)
    Point3d direction(p.x() + x, p.y() + y, p.z() + z);

    // Count intersections with the mesh
    int intersections = tree.numberIntersectedPrimitives(p, direction);

    // If odd number of intersections, point is inside
    if (intersections % 2 == 1) {
        insideCount++;
    }
}

// If majority of rays indicate inside, return true
return insideCount > numberOfChecks / 2;

